from datetime import datetime

import pytest
from isoduration import add_duration


# Basic components
class TestBasicComponents:
    def test_years_basic(self):
        assert add_duration(datetime(2020, 1, 15), "P1Y") == datetime(2021, 1, 15)

    def test_years_multiple(self):
        assert add_duration(datetime(2020, 1, 15), "P5Y") == datetime(2025, 1, 15)

    def test_months_basic(self):
        assert add_duration(datetime(2020, 1, 15), "P1M") == datetime(2020, 2, 15)

    def test_months_multiple(self):
        assert add_duration(datetime(2020, 1, 15), "P12M") == datetime(2021, 1, 15)

    def test_weeks_basic(self):
        assert add_duration(datetime(2020, 1, 1), "P1W") == datetime(2020, 1, 8)

    def test_weeks_multiple(self):
        assert add_duration(datetime(2020, 1, 1), "P2W") == datetime(2020, 1, 15)

    def test_days_basic(self):
        assert add_duration(datetime(2020, 1, 15), "P1D") == datetime(2020, 1, 16)

    def test_days_multiple(self):
        assert add_duration(datetime(2020, 1, 15), "P10D") == datetime(2020, 1, 25)

    def test_hours_basic(self):
        assert add_duration(datetime(2020, 1, 15, 10), "PT1H") == datetime(2020, 1, 15, 11)

    def test_hours_multiple(self):
        assert add_duration(datetime(2020, 1, 15, 10), "PT5H") == datetime(2020, 1, 15, 15)

    def test_minutes_basic(self):
        assert add_duration(datetime(2020, 1, 15, 10, 30), "PT1M") == datetime(2020, 1, 15, 10, 31)

    def test_minutes_multiple(self):
        assert add_duration(datetime(2020, 1, 15, 10, 30), "PT30M") == datetime(2020, 1, 15, 11)

    def test_seconds_basic(self):
        assert add_duration(datetime(2020, 1, 15, 10, 30, 45), "PT1S") == datetime(2020, 1, 15, 10, 30, 46)

    def test_seconds_multiple(self):
        assert add_duration(datetime(2020, 1, 15, 10, 30, 45), "PT30S") == datetime(2020, 1, 15, 10, 31, 15)


# Combined components
class TestCombinedComponents:
    def test_years_and_months(self):
        assert add_duration(datetime(2020, 1, 15), "P1Y2M") == datetime(2021, 3, 15)

    def test_months_and_days(self):
        assert add_duration(datetime(2020, 1, 15), "P2M3D") == datetime(2020, 3, 18)

    def test_days_and_time(self):
        assert add_duration(datetime(2020, 1, 15), "P2DT3H30M") == datetime(2020, 1, 17, 3, 30)

    def test_all_components(self):
        assert add_duration(
            datetime(2020, 1, 15, 10, 30, 45),
            "P1Y2M3DT4H30M15S"
        ) == datetime(2021, 3, 18, 14, 59, 60)

    def test_weeks_alone_valid(self):
        assert add_duration(datetime(2020, 1, 1), "P2W") == datetime(2020, 1, 15)

    def test_weeks_cannot_combine_with_days(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 1), "P1W2D")

    def test_weeks_cannot_combine_with_months(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 1), "P1M1W")

    def test_weeks_cannot_combine_with_years(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 1), "P1Y1W")


# Day-of-month overflow
class TestDayOfMonthOverflow:
    def test_month_overflow_january_to_february_leap_year(self):
        # Jan 31 + 1 month = Feb 29 (leap year)
        assert add_duration(datetime(2024, 1, 31), "P1M") == datetime(2024, 2, 29)

    def test_month_overflow_january_to_february_non_leap_year(self):
        # Jan 31 + 1 month = Feb 28 (non-leap year)
        assert add_duration(datetime(2023, 1, 31), "P1M") == datetime(2023, 2, 28)

    def test_month_overflow_march_to_february_backwards(self):
        # Mar 31 - 1 month = Feb 29 (leap year)
        assert add_duration(datetime(2024, 3, 31), "-P1M") == datetime(2024, 2, 29)

    def test_months_overflow_multiple_steps(self):
        # Jan 31 + 13 months = Feb 29 (leap year 2025 has 28 days)
        # Actually: 2024-01-31 + P1Y1M should use 2025-02-28
        assert add_duration(datetime(2024, 1, 31), "P1Y1M") == datetime(2025, 2, 28)

    def test_month_overflow_may_to_april(self):
        # May 31 + 1 month = June 30 (June has 30 days)
        assert add_duration(datetime(2020, 5, 31), "P1M") == datetime(2020, 6, 30)

    def test_multiple_months_overflow(self):
        # Jan 31 + 2 months = March 31 (exists)
        assert add_duration(datetime(2020, 1, 31), "P2M") == datetime(2020, 3, 31)

    def test_multiple_months_overflow_february(self):
        # Jan 31 + 1 month = Feb 29 (leap year)
        assert add_duration(datetime(2024, 1, 31), "P1M") == datetime(2024, 2, 29)


# Fractional components
class TestFractionalComponents:
    def test_fractional_seconds_dot_separator(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "PT1.5S")
        assert result == datetime(2020, 1, 15, 10, 0, 1, 500000)

    def test_fractional_seconds_comma_separator(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "PT1,5S")
        assert result == datetime(2020, 1, 15, 10, 0, 1, 500000)

    def test_fractional_minutes(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "PT1.5M")
        assert result == datetime(2020, 1, 15, 10, 1, 30)

    def test_fractional_hours(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "PT1.5H")
        assert result == datetime(2020, 1, 15, 11, 30)

    def test_fractional_days(self):
        result = add_duration(datetime(2020, 1, 15), "P1.5D")
        assert result == datetime(2020, 1, 16, 12)

    def test_fractional_weeks(self):
        result = add_duration(datetime(2020, 1, 1), "P0.5W")
        assert result == datetime(2020, 1, 4, 12)

    def test_fractional_seconds_zero_integer_part(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "PT0.5S")
        assert result == datetime(2020, 1, 15, 10, 0, 0, 500000)

    def test_fractional_minutes_zero_integer_part(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "PT0.5M")
        assert result == datetime(2020, 1, 15, 10, 0, 30)

    def test_fractional_seconds_many_decimals(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "PT1.5S")
        assert result == datetime(2020, 1, 15, 10, 0, 1, 500000)


# Negative durations
class TestNegativeDurations:
    def test_negative_days(self):
        assert add_duration(datetime(2020, 1, 15), "-P1D") == datetime(2020, 1, 14)

    def test_negative_months(self):
        assert add_duration(datetime(2020, 3, 15), "-P1M") == datetime(2020, 2, 15)

    def test_negative_months_overflow(self):
        # Mar 31 - 1 month = Feb 29 (leap year)
        assert add_duration(datetime(2024, 3, 31), "-P1M") == datetime(2024, 2, 29)

    def test_negative_months_then_days(self):
        # 2024-03-01 - P1M1D = 2024-02-01 - 1D = 2024-01-31
        assert add_duration(datetime(2024, 3, 1), "-P1M1D") == datetime(2024, 1, 31)

    def test_negative_years_and_months(self):
        assert add_duration(datetime(2020, 3, 15), "-P1Y2M") == datetime(2018, 1, 15)

    def test_negative_time(self):
        assert add_duration(datetime(2020, 1, 15, 10, 30), "-PT1H30M") == datetime(2020, 1, 15, 9)

    def test_explicit_positive_sign(self):
        assert add_duration(datetime(2020, 1, 15), "+P1D") == datetime(2020, 1, 16)


# Microsecond precision and rounding
class TestMicrosecondPrecision:
    def test_fractional_seconds_microsecond_precision(self):
        result = add_duration(datetime(2020, 1, 15), "PT0.000001S")
        assert result == datetime(2020, 1, 15, 0, 0, 0, 1)

    def test_fractional_seconds_rounding_up(self):
        # 1.5000005 seconds should round to 1.500001 seconds
        result = add_duration(datetime(2020, 1, 15), "PT1.5000005S")
        assert result == datetime(2020, 1, 15, 0, 0, 1, 500000)

    def test_large_fractional_combination(self):
        result = add_duration(datetime(2020, 1, 1), "P1.5D")
        assert result == datetime(2020, 1, 2, 12)


# Syntax validation
class TestSyntaxValidation:
    def test_missing_p(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "1D")

    def test_only_p(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P")

    def test_only_pt(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "PT")

    def test_pt_without_time_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P1DT")

    def test_whitespace(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P 1D")

    def test_lowercase_designator(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "p1d")

    def test_duplicate_days(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P1D2D")

    def test_duplicate_hours(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "PT1H2H")

    def test_wrong_order_days_before_months(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P1D1M")

    def test_wrong_order_time_before_date(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "PT1H1D")

    def test_m_ambiguity_after_t(self):
        # PT1M should be 1 minute, not month
        assert add_duration(datetime(2020, 1, 15, 10, 0), "PT1M") == datetime(2020, 1, 15, 10, 1)

    def test_m_ambiguity_before_t(self):
        # P1M should be 1 month, not minute
        assert add_duration(datetime(2020, 1, 15), "P1M") == datetime(2020, 2, 15)

    def test_sign_on_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P-1D")

    def test_no_digits(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "PD")

    def test_fraction_on_years(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P1.5Y")

    def test_fraction_on_months(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P1.5M")

    def test_fraction_not_on_last_component(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P1.5D1H")

    def test_fraction_separator_comma(self):
        result = add_duration(datetime(2020, 1, 15, 10, 0, 0), "PT1,5S")
        assert result == datetime(2020, 1, 15, 10, 0, 1, 500000)

    def test_incomplete_fraction(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P1.D")

    def test_incomplete_fraction_leading(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "P.5D")

    def test_multiple_decimal_points(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "PT1.2.5S")

    def test_empty_string(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2020, 1, 15), "")


# Edge cases and special scenarios
class TestEdgeCases:
    def test_leap_year_february_29(self):
        assert add_duration(datetime(2020, 2, 29), "P1Y") == datetime(2021, 2, 28)

    def test_leap_year_february_29_to_non_leap(self):
        assert add_duration(datetime(2024, 2, 29), "P1Y") == datetime(2025, 2, 28)

    def test_leap_year_february_29_subtract_to_non_leap(self):
        assert add_duration(datetime(2025, 2, 28), "-P1Y") == datetime(2024, 2, 28)

    def test_zero_leading_digits(self):
        assert add_duration(datetime(2020, 1, 15), "P001D") == datetime(2020, 1, 16)

    def test_very_large_duration(self):
        result = add_duration(datetime(2020, 1, 1), "P9999D")
        assert result.year > 2020

    def test_duration_across_month_boundary(self):
        assert add_duration(datetime(2020, 1, 25), "P10D") == datetime(2020, 2, 4)

    def test_duration_across_year_boundary(self):
        assert add_duration(datetime(2020, 12, 25), "P10D") == datetime(2021, 1, 4)

    def test_datetime_with_microseconds(self):
        assert add_duration(datetime(2020, 1, 15, 10, 30, 45, 123456), "P1D") == datetime(2020, 1, 16, 10, 30, 45, 123456)

    def test_fractional_day_into_next_month(self):
        result = add_duration(datetime(2020, 1, 31), "P0.5D")
        assert result == datetime(2020, 2, 1, 12)


# Range validation
class TestRangeValidation:
    def test_datetime_min_year(self):
        # datetime.min is 1 AD, so going before that should fail
        with pytest.raises(ValueError):
            add_duration(datetime(1, 1, 1), "-P1Y")

    def test_datetime_max_year(self):
        # datetime.max is 9999 AD, so going beyond that should fail
        with pytest.raises(ValueError):
            add_duration(datetime(9999, 12, 31), "P1Y")

    def test_valid_near_max(self):
        result = add_duration(datetime(9998, 12, 31), "P365D")
        assert result.year <= 9999


# Specification examples
class TestSpecExamples:
    def test_spec_example_jan_31_plus_1_month(self):
        # From spec: 2024-01-31 plus P1M is 2024-02-29
        assert add_duration(datetime(2024, 1, 31), "P1M") == datetime(2024, 2, 29)

    def test_spec_example_feb_29_plus_1y1m(self):
        # From spec: 2024-02-29 plus P1Y1M is 2025-03-29
        assert add_duration(datetime(2024, 2, 29), "P1Y1M") == datetime(2025, 3, 29)

    def test_spec_example_mar_31_minus_1_month(self):
        # From spec: 2024-03-31 minus P1M is 2024-02-29
        assert add_duration(datetime(2024, 3, 31), "-P1M") == datetime(2024, 2, 29)

    def test_spec_example_mar_1_minus_1m1d(self):
        # From spec: 2024-03-01 minus P1M1D is 2024-01-31
        assert add_duration(datetime(2024, 3, 1), "-P1M1D") == datetime(2024, 1, 31)

    def test_spec_example_p05d_is_12_hours(self):
        # From spec: P0.5D is 12 hours
        assert add_duration(datetime(2020, 1, 15), "P0.5D") == datetime(2020, 1, 15, 12)

    def test_spec_example_pt05h_is_30_minutes(self):
        # From spec: PT0.5H is 30 minutes
        assert add_duration(datetime(2020, 1, 15), "PT0.5H") == datetime(2020, 1, 15, 0, 30)

    def test_spec_example_p05w_is_3_5_days(self):
        # From spec: P0.5W is 3.5 days
        result = add_duration(datetime(2020, 1, 1), "P0.5W")
        assert result == datetime(2020, 1, 4, 12)
